/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    METSalesOrderShipmentLoadTmp        tmptable, tmptable1;
    container                           con;
    int i;
    Map m;
    Set s; 



    tmptable.ConfirmedShipDate = systemDateGet();
    tmptable.CustAccount = '111';
    tmptable.Route = '111';
    tmptable.RouteStopNum = 11;
    tmptable.Warehouse = 'wh';
    tmptable.insert();

    //con = [tmptable];

    tmptable.ConfirmedShipDate = systemDateGet();
    tmptable.CustAccount = '222';
    tmptable.Route = '222';
    tmptable.RouteStopNum = 22;
    tmptable.Warehouse = 'wh';
    tmptable.insert();

    con = [tmptable];


    Common common = con2buf(con);

    tmptable1 = common;

    while select tmptable1
    {
        info (strFmt("Customer %1", tmptable1.CustAccount));
    }


    //// Cycle (iterate) through the container
